theorem MIPRE.conjTranspose_conv_mul_conv (Z : C → Matrix dB dB ℂ) {T : C → Matrix anc' anc' ℂ}
    (hT : IsPVM T) (c : C) :
    (conv (dB := dB) Z T c)ᴴ * conv Z T c = conv (fun a => (Z a)ᴴ * Z a) T c := by sorry

theorem MIPRE.sum_normSq_stateVecB_conv_eq (ψ : dA × dB → ℂ) {e : anc × anc' → ℂ}
    (he : star e ⬝ᵥ e = 1) (Z : C → Matrix dB dB ℂ) {T : C → Matrix anc' anc' ℂ} (hT : IsPVM T) :
    ∑ c, ‖stateVecB (expVec ψ e) (conv Z T c)‖ ^ 2 = ∑ a, ‖stateVecB ψ (Z a)‖ ^ 2 := by sorry
